-- Generated from constructor signatures. Do not edit; see source_imports.shared.contracts.
CREATE FUNCTION atlas.nonblank(value text) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $nonblank$
 SELECT value COLLATE "C" ~  E'[^\\u0009-\\u000d\\u0020\\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]';
$nonblank$;

CREATE FUNCTION atlas.valid_construction_record(method text, arguments jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $contract$
SELECT CASE method
WHEN 'geodesic_trace' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Source Ids","type":"array"},"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"points":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"type":"array"},"title":"Points","type":"array"},"max_step_metres":{"title":"Max Step Metres","type":"number"}},"required":["source_ids","feature_id","points","max_step_metres"],"title":"geodesic_trace","type":"object"}'::json, arguments)
WHEN 'interpreted_geometry' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"Coordinates_Ring_PointCoordinates__":{"items":{"$ref":"#/$defs/Ring_TypeVar_"},"minItems":1,"type":"array"},"Coordinates_TypeVar__MinLen_min_length_4_":{"items":{"$ref":"#/$defs/Position"},"minItems":1,"type":"array"},"Latitude":{"maximum":90,"minimum":-90,"type":"number"},"Longitude":{"maximum":180,"minimum":-180,"type":"number"},"Point":{"additionalProperties":false,"properties":{"type":{"const":"Point","title":"Type","type":"string"},"coordinates":{"$ref":"#/$defs/Position"}},"required":["type","coordinates"],"title":"Geometry","type":"object"},"Polygon":{"additionalProperties":false,"properties":{"type":{"const":"Polygon","title":"Type","type":"string"},"coordinates":{"$ref":"#/$defs/Coordinates_Ring_PointCoordinates__"}},"required":["type","coordinates"],"title":"Geometry","type":"object"},"Position":{"maxItems":2,"minItems":2,"prefixItems":[{"$ref":"#/$defs/Longitude"},{"$ref":"#/$defs/Latitude"}],"type":"array"},"Ring_TypeVar_":{"$ref":"#/$defs/Coordinates_TypeVar__MinLen_min_length_4_","minItems":4},"Selection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"geometry":{"anyOf":[{"$ref":"#/$defs/Point"},{"$ref":"#/$defs/Polygon"}],"title":"Geometry"}},"required":["feature_id","geometry"],"title":"Selection","type":"object"}},"additionalProperties":false,"properties":{"source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Source Ids","type":"array"},"selections":{"items":{"$ref":"#/$defs/Selection"},"title":"Selections","type":"array"}},"required":["source_ids","selections"],"title":"interpreted_geometry","type":"object"}'::json, arguments)
WHEN 'osm_way_chain' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"way_source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Way Source Ids","type":"array"},"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"evidence_source_ids":{"anyOf":[{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"type":"array"},{"type":"null"}],"title":"Evidence Source Ids"}},"required":["way_source_ids","feature_id"],"title":"osm_way_chain","type":"object"}'::json, arguments)
WHEN 's130_areas' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"FeatureIdentity":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"}},"required":["feature_id","source_feature_id"],"title":"FeatureIdentity","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"gml_member":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Gml Member","type":"string"},"selections":{"items":{"$ref":"#/$defs/FeatureIdentity"},"title":"Selections","type":"array"}},"required":["source_id","gml_member","selections"],"title":"s130_areas","type":"object"}'::json, arguments)
WHEN 'selected_osm_features' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"OsmSelection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"},"object_type":{"enum":["node","way","relation"],"title":"Object Type","type":"string"},"expected_tags":{"additionalProperties":{"type":"string"},"title":"Expected Tags","type":"object"}},"required":["feature_id","source_feature_id","object_type"],"title":"OsmSelection","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"selections":{"items":{"$ref":"#/$defs/OsmSelection"},"title":"Selections","type":"array"}},"required":["source_id","selections"],"title":"selected_osm_features","type":"object"}'::json, arguments)
WHEN 'selected_vector_features' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"VectorSelection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"},"polygon_containing":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"title":"Polygon Containing","type":"array"},"fill_holes":{"title":"Fill Holes","type":"boolean"}},"required":["feature_id","source_feature_id"],"title":"VectorSelection","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"id_field":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Id Field","type":"string"},"selections":{"items":{"$ref":"#/$defs/VectorSelection"},"title":"Selections","type":"array"},"member":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"null"}],"title":"Member"},"layer":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"null"}],"title":"Layer"}},"required":["source_id","id_field","selections"],"title":"selected_vector_features","type":"object"}'::json, arguments)
WHEN 'watershed_boundary' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"BoundaryPoint":{"anyOf":[{"$ref":"#/$defs/SourcePoint"},{"$ref":"#/$defs/DivideCorner"}]},"BoundarySection":{"anyOf":[{"$ref":"#/$defs/SourceSection"},{"$ref":"#/$defs/DivideSection"},{"$ref":"#/$defs/DivideViaPoints"},{"$ref":"#/$defs/FlowSection"},{"$ref":"#/$defs/GeodesicSection"}]},"ClosedSink":{"additionalProperties":false,"properties":{"point":{"$ref":"#/$defs/SourcePoint"},"group":{"anyOf":[{"type":"integer"},{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"}],"title":"Group"}},"required":["point","group"],"title":"ClosedSink","type":"object"},"CoordinatePoint":{"additionalProperties":false,"properties":{"point":{"$ref":"#/$defs/Position"}},"required":["point"],"title":"CoordinatePoint","type":"object"},"DivideCorner":{"additionalProperties":false,"properties":{"nearest_divide":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Nearest Divide","type":"string"},"near":{"$ref":"#/$defs/SourcePoint"}},"required":["nearest_divide","near"],"title":"DivideCorner","type":"object"},"DivideSection":{"additionalProperties":false,"properties":{"divide":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Divide","type":"string"}},"required":["divide"],"title":"DivideSection","type":"object"},"DivideViaPoints":{"additionalProperties":false,"properties":{"divide":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Divide","type":"string"},"via":{"items":{"$ref":"#/$defs/SourcePoint"},"title":"Via","type":"array"},"max_step_m":{"title":"Max Step M","type":"number"}},"required":["divide","via","max_step_m"],"title":"DivideViaPoints","type":"object"},"DrainageSettings":{"additionalProperties":false,"properties":{"basins":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Basins","type":"array"},"basin_attribute":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basin Attribute","type":"string"},"groups":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}]},"type":"array"}},"title":"Groups","type":"object"},"waterways":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Waterways","type":"array"},"reverse_waterways":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}]},"title":"Reverse Waterways","type":"array"},"waterway_groups":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}]},"type":"array"}},"title":"Waterway Groups","type":"object"}},"required":["basins","basin_attribute","groups"],"title":"DrainageSettings","type":"object"},"FileSelection":{"additionalProperties":false,"properties":{"source":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source","type":"string"},"member":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Member","type":"string"}},"required":["source"],"title":"FileSelection","type":"object"},"FlowConnection":{"additionalProperties":false,"properties":{"terrain":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Terrain","type":"string"},"point":{"$ref":"#/$defs/SourcePoint"},"inside_group":{"anyOf":[{"type":"integer"},{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"}],"title":"Inside Group"},"outside_groups":{"items":{"type":"integer"},"title":"Outside Groups","type":"array"},"max_step_m":{"title":"Max Step M","type":"number"}},"required":["terrain","point","inside_group","outside_groups","max_step_m"],"title":"FlowConnection","type":"object"},"FlowSection":{"additionalProperties":false,"properties":{"flow":{"$ref":"#/$defs/FlowConnection"}},"required":["flow"],"title":"FlowSection","type":"object"},"GeoJSONLine":{"additionalProperties":false,"properties":{"source":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source","type":"string"},"member":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Member","type":"string"},"geojson_feature":{"minimum":0,"title":"Geojson Feature","type":"integer"}},"required":["source","geojson_feature