roperties":{"bounds":{"maxItems":4,"minItems":4,"prefixItems":[{"type":"number"},{"type":"number"},{"type":"number"},{"type":"number"}],"title":"Bounds","type":"array"},"crs":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Crs"},"output_bounds":{"anyOf":[{"maxItems":4,"minItems":4,"prefixItems":[{"type":"number"},{"type":"number"},{"type":"number"},{"type":"number"}],"type":"array"},{"type":"null"}],"title":"Output Bounds"}},"required":["bounds"],"title":"TerrainDomain","type":"object"},"TerrainSettings":{"additionalProperties":false,"properties":{"domains":{"items":{"$ref":"#/$defs/TerrainDomain"},"title":"Domains","type":"array"},"primary":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Primary","type":"array"},"drainage":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Drainage","type":"string"},"interfaces":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"anyOf":[{"type":"integer"},{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"}]},{"anyOf":[{"type":"integer"},{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"}]}],"type":"array"},"title":"Interfaces","type":"array"},"secondary":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Secondary","type":"array"},"height_offset":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Height Offset","type":"string"},"closed_sinks":{"items":{"$ref":"#/$defs/ClosedSink"},"title":"Closed Sinks","type":"array"},"ocean_mask":{"$ref":"#/$defs/OceanMask"}},"required":["domains","primary","drainage","interfaces"],"title":"TerrainSettings","type":"object"}},"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"sources":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"}},"title":"Sources","type":"object"},"lines":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"anyOf":[{"$ref":"#/$defs/GeoJSONLine"},{"$ref":"#/$defs/OsmWayLine"},{"$ref":"#/$defs/OsmRiverLine"}]}},"title":"Lines","type":"object"},"sections":{"items":{"$ref":"#/$defs/BoundarySection"},"title":"Sections","type":"array"},"joins":{"items":{"$ref":"#/$defs/JoinSelection"},"title":"Joins","type":"array"},"start":{"$ref":"#/$defs/BoundaryPoint"},"end":{"$ref":"#/$defs/BoundaryPoint"},"terrains":{"anyOf":[{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"$ref":"#/$defs/TerrainSettings"}},"type":"object"},{"type":"null"}],"title":"Terrains"},"drainage":{"anyOf":[{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\